import{V as e,Z as t,et as n,mt as r,nt as i,tt as a}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var o=JSON.parse(`{"title":"Site Form","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/form/form.md","filePath":"documentation/form/form.md","lastUpdated":1788551488000}`),s={name:`documentation/form/form.md`};function c(e,o,s,c,l,u){return r(),n(`div`,null,[...o[0]||=[a(`<h1 id="site-form" tabindex="-1">Site Form <a class="header-anchor" href="#site-form" aria-label="Permalink to “Site Form”">​</a></h1><p>A <strong>Site Form</strong> defines a specific page or workflow step within your website automation. Each form contains page URL matching rules, execution timing delays, and individual form field definitions.</p><img src="/image/form-01.png" alt="Form Management Interface" style="max-width:100%;border-radius:8px;margin:16px 0;"><hr><h2 id="form-options" tabindex="-1">Form Options <a class="header-anchor" href="#form-options" aria-label="Permalink to “Form Options”">​</a></h2><p>Essential form configuration options for automated form filling:</p><table tabindex="0"><thead><tr><th>Form Option</th><th>Required</th><th>Description</th><th>Example Values</th></tr></thead><tbody><tr><td><strong>Page URL</strong></td><td>Yes</td><td>Target page URL for form execution</td><td><code>https://example.com/contact</code></td></tr><tr><td><a href="#form-url-match-types"><strong>URL Match Type</strong></a></td><td>Yes</td><td>Method used to match the target page URL</td><td><strong>Full URL</strong>, <strong>Pathname</strong>, <strong>Hostname</strong>, <strong>RegEx</strong></td></tr><tr><td><strong>Description</strong></td><td>No</td><td>Optional note for form identification</td><td><code>Contact Form</code>, <code>Registration Page</code></td></tr><tr><td><strong>Active/Inactive</strong></td><td>Yes</td><td>Enable or disable form processing</td><td><strong>Active</strong>, <strong>Inactive</strong></td></tr><tr><td><a href="#form-timing-configuration"><strong>Delay Time Before Running This Form</strong></a></td><td>No</td><td>Wait time before form execution begins</td><td><code>0</code>, <code>500</code>, <code>1000</code> (milliseconds)</td></tr><tr><td><a href="#form-timing-configuration"><strong>Delay Time After Running This Form</strong></a></td><td>No</td><td>Wait time after form execution completes</td><td><code>0</code>, <code>500</code>, <code>1000</code> (milliseconds)</td></tr></tbody></table><hr><h2 id="insert-site-form" tabindex="-1">Insert Site Form <a class="header-anchor" href="#insert-site-form" aria-label="Permalink to “Insert Site Form”">​</a></h2><p>To create and configure a new form within a registered site:</p><h3 id="step-by-step-process" tabindex="-1">Step-by-Step Process <a class="header-anchor" href="#step-by-step-process" aria-label="Permalink to “Step-by-Step Process”">​</a></h3><ol><li>Register or select a site from the <a href="/documentation/site/site.html#insert-site">Site Management Dashboard</a>.</li><li>Click the <strong>Edit Site</strong> button (pencil icon) to open site settings.</li><li>Open the <strong>Site Form Pages</strong> tab.</li><li>Click the <strong>Insert Form</strong> button (located to the left of the delete button).</li><li>Fill in the <strong>Page URL</strong> and choose the appropriate <a href="#form-url-match-types"><strong>URL Match Type</strong></a>.</li><li>Click <strong>Save</strong> to confirm.</li></ol><img src="/image/insert-site-form.gif" width="650" height="650" alt="Insert Site Manually" style="max-width:100%;border-radius:8px;margin:16px 0;"><blockquote><p><strong>Shortcut:</strong> You can also insert a form directly from the active tab by pressing <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd> or right-clicking on the page and choosing <strong>Insert Form</strong>.</p></blockquote><h3 id="form-management-controls" tabindex="-1">Form Management Controls <a class="header-anchor" href="#form-management-controls" aria-label="Permalink to “Form Management Controls”">​</a></h3><table tabindex="0"><thead><tr><th>Control</th><th>Description</th><th>Purpose</th></tr></thead><tbody><tr><td><strong>Page URL</strong></td><td>Target URL address</td><td>Defines where the extension executes</td></tr><tr><td><strong>Match URL Types</strong></td><td>Matching method</td><td>Target specific URLs or broad patterns</td></tr><tr><td><strong>Description</strong></td><td>Label / Notes</td><td>Distinguish between multiple forms</td></tr><tr><td><strong>Active / Inactive</strong></td><td>Status toggle</td><td>Temporarily pause a form without deleting it</td></tr><tr><td><strong>Move Up / Down</strong></td><td>Drag or arrow buttons</td><td>Change the sequential execution order</td></tr><tr><td><strong>Form Fields</strong></td><td>Field count button</td><td>Open and manage field configurations</td></tr><tr><td><strong>Edit Form</strong></td><td>Settings icon</td><td>Update page URL or match type</td></tr><tr><td><strong>Duplicate Form</strong></td><td>Row action</td><td>Clone form settings and all fields</td></tr><tr><td><strong>Copy Form</strong></td><td>Row action</td><td>Copy form schema to clipboard</td></tr><tr><td><strong>Paste Form</strong></td><td>Row action</td><td>Import form schema from clipboard</td></tr><tr><td><strong>Delete Form</strong></td><td>Trash icon</td><td>Permanently remove the form</td></tr></tbody></table><hr><h2 id="form-url-match-types" tabindex="-1">Form URL Match Types <a class="header-anchor" href="#form-url-match-types" aria-label="Permalink to “Form URL Match Types”">​</a></h2><p>URL matching rules determine when the extension should activate on the browser tab:</p><table tabindex="0"><thead><tr><th>Match Type</th><th>Description</th><th>Best Use Case</th><th>Example</th></tr></thead><tbody><tr><td><strong>Match with Full URL</strong></td><td>Exact match including query strings</td><td>Strict single-page targeting</td><td><code>https://example.com/contact?ref=web</code></td></tr><tr><td><strong>Match with URL pathname</strong></td><td>Matches the path only, ignoring domain and queries</td><td>Same path across multiple domains/environments</td><td><code>/contact</code>, <code>/register</code></td></tr><tr><td><strong>Match with URL hostname</strong></td><td>Matches the root domain only</td><td>Execute across all pages on a website</td><td><code>example.com</code></td></tr><tr><td><strong>Match with RegEx</strong></td><td>Regular expression pattern matching</td><td>Dynamic URLs with variable IDs or tokens</td><td><code>.*\\/user\\/\\d+\\/edit</code></td></tr></tbody></table><h3 id="regex-matching-examples" tabindex="-1">RegEx Matching Examples <a class="header-anchor" href="#regex-matching-examples" aria-label="Permalink to “RegEx Matching Examples”">​</a></h3><p>The extension provides helper syntax tokens alongside standard JavaScript regular expressions:</p><table tabindex="0"><thead><tr><th>Pattern</th><th>Description</th><th>Matches</th></tr></thead><tbody><tr><td><code>(:any)</code></td><td>Matches any sequence of characters</td><td><code>abc</code>, <code>123</code>, <code>xyz</code></td></tr><tr><td><code>(:any(:end))</code></td><td>Matches any sequence of characters up to the end of the URL <em>(do not place in the middle)</em></td><td><code>abc</code>, <code>123xyz</code></td></tr></tbody></table><p><strong>URL Matching Comparison:</strong></p><table tabindex="0"><thead><tr><th>Site Form URL with RegEx</th><th>Tested Page URL</th><th style="text-align:center;">Match Status</th></tr></thead><tbody><tr><td><code>http://demo.in/new/(:any)/edit</code></td><td><code>http://demo.in/new/jK33k3ui/edit</code></td><td style="text-align:center;">Matched</td></tr><tr><td><code>http://demo.in/new/(:any(:end))</code></td><td><code>http://demo.in/new/jK33k3ui</code></td><td style="text-align:center;">Matched</td></tr></tbody></table><img src="/image/form-url-with-regex.png" width="500" height="500" alt="RegEx URL Matching" style="max-width:100%;border-radius:8px;margin:16px 0;"><div class="tip custom-block"><p class="custom-block-title">Testing RegEx Patterns</p><p>You can test your regular expressions using the extension&#39;s built-in <a href="/documentation/regex.html">RegEx Tester</a>.</p></div><hr><h2 id="form-timing-configuration" tabindex="-1">Form Timing Configuration <a class="header-anchor" href="#form-timing-configuration" aria-label="Permalink to “Form Timing Configuration”">​</a></h2><p>Timing settings control execution pauses to accommodate slow network responses, animations, or dynamic page rendering:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th><th>Default</th><th>Impact</th></tr></thead><tbody><tr><td><strong>Delay Time Before Running This Form</strong></td><td>Milliseconds to wait after page load before starting automation</td><td><code>0 ms</code></td><td>Allows client-side single-page apps (SPAs) to finish rendering</td></tr><tr><td><strong>Delay Time After Running This Form</strong></td><td>Milliseconds to wait after all fields complete</td><td><code>0 ms</code></td><td>Ensures AJAX submissions or redirects complete smoothly</td></tr></tbody></table>`,31),t(`div`,null,[t(`h3`,{id:`randomized-delays`,tabindex:`-1`},[i(`Randomized Delays `),t(`a`,{class:`header-anchor`,href:`#randomized-delays`,"aria-label":`Permalink to “Randomized Delays”`},`​`)]),t(`p`,null,`To prevent bot-detection algorithms from spotting consistent automation intervals, you can specify randomized time ranges using variables:`),t(`div`,{class:`language-text`},[t(`button`,{title:`Copy Code`,class:`copy`}),t(`span`,{class:`lang`},`text`),t(`pre`,{class:`shiki shiki-themes github-light github-dark`,style:{"--shiki-light":`#24292e`,"--shiki-dark":`#e1e4e8`,"--shiki-light-bg":`#fff`,"--shiki-dark-bg":`#24292e`},tabindex:`0`,dir:`ltr`,"v-pre":``},[t(`code`,null,[t(`span`,{class:`line`},[t(`span`,null,`{{random.integer[1000][2500]}}`)])])])]),t(`p`,null,`This instructs the extension to generate a fresh delay between 1000ms and 2500ms on each run.`)],-1),a(`<hr><h2 id="insert-multiple-forms" tabindex="-1">Insert Multiple Forms <a class="header-anchor" href="#insert-multiple-forms" aria-label="Permalink to “Insert Multiple Forms”">​</a></h2><p>For complex multi-page workflows (such as step-by-step registration wizards or checkout funnels), you can register multiple forms under a single site configuration.</p><h3 id="copy-site-id" tabindex="-1">Copy Site ID <a class="header-anchor" href="#copy-site-id" aria-label="Permalink to “Copy Site ID”">​</a></h3><ol><li>Open the extension popup and locate the parent site in your site list.</li><li>Click the <strong>Copy Site ID</strong> icon next to the site title.</li><li>The unique site ID is copied to your clipboard.</li></ol><img src="/image/copy_site_id.png" width="350" height="350" alt="Copy Site ID" style="max-width:350px;border-radius:8px;margin:16px 0;"><h3 id="adding-forms-via-context-menu" tabindex="-1">Adding Forms via Context Menu <a class="header-anchor" href="#adding-forms-via-context-menu" aria-label="Permalink to “Adding Forms via Context Menu”">​</a></h3><ol><li>Navigate to the next page of your multi-step form in your browser.</li><li>Right-click on the extension toolbar icon or anywhere on the page.</li><li>Select <strong>Insert Form</strong> (or press <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>F</kbd>).</li><li>When prompted, paste the copied <strong>Site ID</strong> and confirm.</li><li>The new page is instantly linked to the existing site configuration.</li></ol><img src="/image/insert-site-form-01.png" width="350" height="350" alt="Insert Additional Form" style="max-width:350px;border-radius:8px;margin:16px 0;"><hr><h2 id="insert-form-fields" tabindex="-1">Next Steps: Configuring Form Fields <a class="header-anchor" href="#insert-form-fields" aria-label="Permalink to “Next Steps: Configuring Form Fields”">​</a></h2><p>Once your form page is registered, configure the individual input fields to automate:</p><ol><li>Click on the form&#39;s <strong>Fields</strong> button in the extension.</li><li>Add input fields matching your elements and <code>.xlsx</code> spreadsheet headers.</li><li>Define selectors, field types, and default fallback values.</li></ol><p>For complete field setup instructions, see the <a href="/documentation/form-fields/field.html">Form Field Guide</a> and the <a href="/documentation/form-fields/field-types.html">Field Types Catalog</a>.</p>`,14)]])}var l=e(s,[[`render`,c]]);export{o as __pageData,l as default};